import{_ as r,c as o,o as t,ag as n}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Cyber Incident Response Guide (Personal)","description":"","frontmatter":{"title":"Cyber Incident Response Guide (Personal)"},"headers":[],"relativePath":"cybersecurity/cyber-incident-response-guide-personal.md","filePath":"cybersecurity/cyber-incident-response-guide-personal.md","lastUpdated":null}'),a={name:"cybersecurity/cyber-incident-response-guide-personal.md"};function i(s,e,l,c,u,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="cyber-incident-response-guide-personal" tabindex="-1">Cyber Incident Response Guide (Personal) <a class="header-anchor" href="#cyber-incident-response-guide-personal" aria-label="Permalink to &quot;Cyber Incident Response Guide (Personal)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><ul><li><a href="#identify">Identify</a></li><li><a href="#secure">Secure</a></li><li><a href="#restore">Restore</a></li><li><a href="#report">Report</a></li><li><a href="#learn">Learn</a></li><li><a href="#monitor">Monitor</a></li></ul><p><strong>Prevention is the best option!</strong> The <a href="/general/dfp-guide.html">DFP Guide</a> can help you prevent incidents and prepare backups for recovery.</p><p>This guide is designed to help you react to potential cyber incidents on personal devices, accounts, and networks. If you&#39;re feeling overwhelmed, don&#39;t worry—we&#39;ll walk you through each step.</p><h3 id="prevention" tabindex="-1">Prevention <a class="header-anchor" href="#prevention" aria-label="Permalink to &quot;Prevention&quot;">​</a></h3><p>Preventing cyber incidents is crucial. Follow best practices to secure your devices, accounts, and networks. Refer to the <a href="/general/dfp-guide.html">DFP Guide</a> for detailed instructions.</p><h2 id="identify" tabindex="-1">Identify <a class="header-anchor" href="#identify" aria-label="Permalink to &quot;Identify&quot;">​</a></h2><p>The first step is to <strong>identify</strong> what happened. Don&#39;t panic—we&#39;ll help you figure it out.</p><h3 id="possible-signs-of-a-cyber-incident" tabindex="-1">Possible Signs of a Cyber Incident <a class="header-anchor" href="#possible-signs-of-a-cyber-incident" aria-label="Permalink to &quot;Possible Signs of a Cyber Incident&quot;">​</a></h3><h4 id="online-account-issues" tabindex="-1">Online Account Issues <a class="header-anchor" href="#online-account-issues" aria-label="Permalink to &quot;Online Account Issues&quot;">​</a></h4><p>Ask yourself:</p><ul><li><strong>Are you locked out of your account?</strong></li><li><strong>Is there money missing from your financial account?</strong></li><li><strong>Do you see changes or activities in your accounts that you didn&#39;t make?</strong></li></ul><p>If you answer <strong>YES</strong> to any of these questions, proceed to <a href="#secure-your-online-accounts">Secure Your Online Accounts</a>.</p><p>If you answer <strong>NO</strong>, continue monitoring your accounts for unusual activity.</p><p>If you&#39;re <strong>UNSURE</strong>, consider changing your passwords as a precaution and enabling multi-factor authentication.</p><h4 id="device-behavior-issues" tabindex="-1">Device Behavior Issues <a class="header-anchor" href="#device-behavior-issues" aria-label="Permalink to &quot;Device Behavior Issues&quot;">​</a></h4><p>Ask yourself:</p><ul><li><strong>Is your computer acting on its own (e.g., mouse moving, unexpected restarts)?</strong></li><li><strong>Did you receive a ransomware message?</strong></li><li><strong>Did you get a fake antivirus or update message?</strong></li><li><strong>Have you noticed new plugins, toolbars, or applications that you didn&#39;t install?</strong></li><li><strong>Is your device running slowly or behaving abnormally?</strong></li><li><strong>Are you seeing unexpected pop-ups on your computer?</strong></li><li><strong>Are your internet searches being redirected to unfamiliar sites?</strong></li></ul><p>If you answer <strong>YES</strong> to any of these questions, proceed to <a href="#log-file-analysis">Log File Analysis</a> and <a href="#secure-your-local-devices">Secure Your Local Devices</a>.</p><p>If you answer <strong>NO</strong>, keep an eye on your device performance and consider running a periodic malware scan.</p><p>If you&#39;re <strong>UNSURE</strong>, run a malware scan and ensure all software is updated.</p><h4 id="data-leaks-and-breaches" tabindex="-1">Data Leaks and Breaches <a class="header-anchor" href="#data-leaks-and-breaches" aria-label="Permalink to &quot;Data Leaks and Breaches&quot;">​</a></h4><p>Ask yourself:</p><ul><li><strong>Has your private information (like photos or personal details) been shared online without your permission?</strong></li><li><strong>Have personal images, videos, or other media been shared online without your consent?</strong></li><li><strong>Have you received notifications from companies about a hack of their systems?</strong></li><li><strong>Do you suspect a data breach involving your accounts?</strong></li></ul><p>If you answer <strong>YES</strong> to any of these questions:</p><ul><li>Alert family and friends to be cautious of anyone pretending to be you.</li><li><a href="https://inteltechniques.com/freeze.html" target="_blank" rel="noreferrer">Freeze Your Credit</a> to prevent identity theft.</li><li>Proceed to <a href="#identify-and-lock-down">Identify and Lock Down</a> and <a href="#secure-your-online-accounts">Secure Your Online Accounts</a>.</li></ul><p>If you answer <strong>NO</strong>, continue practicing good security hygiene and monitor for any alerts from services you use.</p><p>If you&#39;re <strong>UNSURE</strong>, check if any of your accounts have been involved in known breaches using <a href="https://haveibeenpwned.com/" target="_blank" rel="noreferrer">Have I Been Pwned</a>.</p><h4 id="social-engineering-and-scams" tabindex="-1">Social Engineering and Scams <a class="header-anchor" href="#social-engineering-and-scams" aria-label="Permalink to &quot;Social Engineering and Scams&quot;">​</a></h4><p><strong>Phishing Attempts</strong></p><p>Ask yourself:</p><ul><li><strong>Did you receive an email or message asking for personal or financial information?</strong></li></ul><p>If <strong>YES</strong>:</p><ul><li>Do not respond or click on any links.</li><li>Mark the email as spam and delete it.</li><li>Proceed to <a href="#secure-your-network">Secure Your Network</a> if you&#39;ve interacted with the message.</li></ul><p>If <strong>NO</strong>, remain vigilant against suspicious communications.</p><p>If you&#39;re <strong>UNSURE</strong>, verify the sender&#39;s identity through another communication channel before taking action.</p><p><strong>Financial Scams</strong></p><p>Ask yourself:</p><ul><li><strong>Did someone request money or your banking information?</strong></li></ul><p>If <strong>YES</strong>:</p><ul><li>Be cautious. Scammers often pressure you using fear or urgency.</li><li>Read about <a href="http://www.consumerfinance.gov/ask-cfpb/what-are-some-common-types-of-scams-en-2092/" target="_blank" rel="noreferrer">common financial scams</a>.</li><li>Proceed to report the incident if necessary.</li></ul><p>If <strong>NO</strong>, stay alert for unusual requests for money or information.</p><p>If you&#39;re <strong>UNSURE</strong>, consult with someone trustworthy before proceeding with any requests.</p><h4 id="accidents" tabindex="-1">Accidents <a class="header-anchor" href="#accidents" aria-label="Permalink to &quot;Accidents&quot;">​</a></h4><p>Ask yourself:</p><ul><li><strong>Has your device been lost or stolen?</strong></li></ul><p>If <strong>YES</strong>:</p><ul><li>Change passwords for your accounts and enable two-factor authentication.</li><li>Try to locate the device using a tracking app or service.</li><li>Consider remotely wiping the device to protect your data.</li></ul><p>If <strong>NO</strong>, ensure that tracking features are enabled on all devices as a precaution.</p><p>If you&#39;re <strong>UNSURE</strong>, check recent locations if tracking was enabled previously.</p><ul><li><strong>Did you accidentally delete important files or information?</strong></li></ul><p>If <strong>YES</strong>, proceed to <a href="#restore">Restore</a> for data recovery steps.</p><p>If <strong>NO</strong>, consider setting up regular backups to prevent future data loss issues.</p><p>If you&#39;re <strong>UNSURE</strong>, check if the files are in the recycle bin or use recovery software as needed.</p><h4 id="log-file-analysis" tabindex="-1">Log File Analysis <a class="header-anchor" href="#log-file-analysis" aria-label="Permalink to &quot;Log File Analysis&quot;">​</a></h4><p>To analyze log files for suspicious activity effectively, refer to our detailed guide: How to Search Log Files. This guide provides instructions for operating systems including iOS, Android, Windows, MacOS, and Linux. It covers accessing logs, identifying suspicious activities, and interpreting log entries related to security incidents.</p><p>While you are on this step you should look at <a href="#secure-your-local-devices">Secure Your Local Devices</a> as well.</p><h2 id="secure" tabindex="-1">Secure <a class="header-anchor" href="#secure" aria-label="Permalink to &quot;Secure&quot;">​</a></h2><p>Now that you&#39;ve identified a potential issue, let&#39;s <strong>secure</strong> your digital environment.</p><h3 id="secure-your-online-accounts" tabindex="-1">Secure Your Online Accounts <a class="header-anchor" href="#secure-your-online-accounts" aria-label="Permalink to &quot;Secure Your Online Accounts&quot;">​</a></h3><p>Take these steps immediately:</p><ol><li><strong>Change Passwords</strong>: Update passwords for all important accounts. Use a <a href="/general/guide-to-password-managers.html">Password Manager</a> to store them securely.</li><li><strong>Enable Multi-Factor Authentication (MFA)</strong>: This adds an extra layer of security. See our <a href="/general/mfa-guide.html">MFA Guide</a> for help.</li><li><strong>Check for Data Breaches</strong>: Visit <a href="https://haveibeenpwned.com/" target="_blank" rel="noreferrer">Have I Been Pwned</a> to see if your email has been compromised.</li><li><strong>Prioritize Critical Accounts</strong>: <ul><li>Email Accounts: Especially ones used for account recovery.</li><li>Financial Accounts: Banks, credit cards, crypto wallets.</li><li>Mobile Carrier Account: To prevent SIM swapping.</li><li>Social Media: To prevent impersonation.</li></ul></li><li><strong>Remove Personal Data from Data Brokers</strong>: Use opt-out lists like the <a href="https://github.com/yaelwrites/Big-Ass-Data-Broker-Opt-Out-List" target="_blank" rel="noreferrer">Big Ass Data Broker Opt-Out List</a>.</li></ol><h3 id="secure-your-local-devices" tabindex="-1">Secure Your Local Devices <a class="header-anchor" href="#secure-your-local-devices" aria-label="Permalink to &quot;Secure Your Local Devices&quot;">​</a></h3><p>Take these steps to secure your devices:</p><ol><li><strong>Disconnect from the Internet</strong>: Unplug your network cable or turn off Wi-Fi to prevent further unauthorized access.</li><li><strong>Run a Malware Scan</strong>: Use reputable antivirus software to scan and remove any threats.</li><li><strong>Update Your Software</strong>: Ensure your operating system and applications are up to date.</li><li><strong>Review Installed Programs</strong>: Uninstall any software you don&#39;t recognize.</li><li><strong>Check Your Browser Extensions</strong>: Remove any unfamiliar plugins or toolbars.</li><li><strong>Change Your Device Passwords</strong>: Use strong, unique passwords.</li><li><strong>Consider Professional Help</strong>: If you&#39;re unsure, seek assistance from a trusted professional.</li></ol><h3 id="secure-your-network" tabindex="-1">Secure Your Network <a class="header-anchor" href="#secure-your-network" aria-label="Permalink to &quot;Secure Your Network&quot;">​</a></h3><p>Ensure your network is safe:</p><ol><li><strong>Change Router Passwords</strong>: Update the default login credentials.</li><li><strong>Update Router Firmware</strong>: Install the latest firmware updates.</li><li><strong>Disable Remote Management</strong>: Prevent external access to your router settings.</li><li><strong>Set Up a Guest Wi-Fi Network</strong>: Isolate your main devices from guests.</li><li><strong>Monitor Network Traffic</strong>: Use tools to detect unusual activity.</li><li>Refer to the <a href="/general/router-hardening.html">Router Hardening</a> Guide for detailed steps.</li></ol><h3 id="identify-and-lock-down" tabindex="-1">Identify and Lock Down <a class="header-anchor" href="#identify-and-lock-down" aria-label="Permalink to &quot;Identify and Lock Down&quot;">​</a></h3><p>Protect yourself from identity theft:</p><ol><li><a href="https://inteltechniques.com/freeze.html" target="_blank" rel="noreferrer">Freeze Your Credit</a>: Contact major credit bureaus. See <a href="https://inteltechniques.com/freeze.html" target="_blank" rel="noreferrer">IntelTechniques Credit Freeze Guide</a>.</li><li><strong>Review Financial Statements</strong>: Look for unauthorized transactions.</li><li><strong>Update Security Settings</strong>: Strengthen privacy and security settings on all accounts.</li><li><strong>Remove Unnecessary Personal Information</strong>: From social media and other online platforms.</li></ol><h2 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore&quot;">​</a></h2><p>Recover from the incident:</p><ol><li><p><strong>Account Recovery</strong>:</p><ul><li>Reset passwords and security questions.</li><li>Use masked emails for sensitive accounts.</li></ul></li><li><p><strong>Data Recovery</strong>:</p><ul><li>Restore files from backups if available.</li><li>Use data recovery software or consult a professional.</li></ul></li><li><p><strong>Reinstall Operating System</strong>:</p><ul><li>In severe cases, consider reinstalling your OS to ensure all malware is removed.</li></ul></li></ol><h2 id="report" tabindex="-1">Report <a class="header-anchor" href="#report" aria-label="Permalink to &quot;Report&quot;">​</a></h2><p>Reporting helps prevent future incidents:</p><ol><li><strong>Contact Financial Institutions</strong>: Inform them of any unauthorized activity.</li><li><strong>Report to Law Enforcement</strong>: File a report with your local police department.</li><li><strong>Notify Affected Parties</strong>: Let friends and family know if they might be impacted.</li><li><strong>File Complaints</strong>: <ul><li>With the <a href="https://reportfraud.ftc.gov/#/" target="_blank" rel="noreferrer">FTC</a> for scams and fraud.</li><li>With other relevant authorities.</li></ul></li></ol><h2 id="learn" tabindex="-1">Learn <a class="header-anchor" href="#learn" aria-label="Permalink to &quot;Learn&quot;">​</a></h2><p>Understand and learn from the incident:</p><ol><li><strong>Review What Happened</strong>: Identify how the incident occurred.</li><li><strong>Educate Yourself</strong>: Read about best security practices.</li><li><strong>Implement Preventive Measures</strong>: Update your habits and tools to enhance security.</li></ol><h2 id="monitor" tabindex="-1">Monitor <a class="header-anchor" href="#monitor" aria-label="Permalink to &quot;Monitor&quot;">​</a></h2><p>Keep an eye out to prevent future incidents:</p><ol><li><strong>Regularly Check Accounts</strong>: Monitor bank statements and account activities.</li><li><strong>Use Monitoring Services</strong>: Consider credit and identity theft monitoring services.</li><li><strong>Use Monitoring Apps</strong>: Little Snitch and other options are broken down in <a href="https://alternativeto.net/software/little-snitch/" target="_blank" rel="noreferrer">AlternativeTo.net</a></li><li><strong>Stay Updated</strong>: Follow reputable sources for security news.</li></ol>',84)])])}const h=r(a,[["render",i]]);export{p as __pageData,h as default};
